-- UNA-Migration-Min-System-Version: 15.0.0-RC4
-- The new default email header and footer: a card on a grey page with the logo ({site_logo}: the email logo or the site logo
-- from Designer, the dark mode one in dark mode, the site title when there is none) and the site name above a grey panel
-- with the message, the links below it. Only a header or footer that is still the previous default is replaced.
UPDATE `sys_options` SET `value` = '<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">\r\n<html dir="ltr" lang="en">\r\n<head>\r\n<meta content="text/html; charset=UTF-8" http-equiv="Content-Type" />\r\n<meta name="x-apple-disable-message-reformatting" />\r\n<meta name="viewport" content="width=device-width, initial-scale=1" />\r\n<meta name="color-scheme" content="light dark" />\r\n<meta name="supported-color-schemes" content="light dark" />\r\n<style>\r\n:root { color-scheme: light dark; supported-color-schemes: light dark; }\r\n@media (max-width:600px) {\r\n    .m-mt-0 { margin-top:0 !important; }\r\n    .m-px-2 { padding-right:8px !important; padding-left:8px !important; }\r\n    .m-px-6 { padding-right:24px !important; padding-left:24px !important; }\r\n    .m-py-12 { padding-top:48px !important; padding-bottom:48px !important; }\r\n}\r\n.bx-email-muted a { color:#7b7d81; text-decoration:none; }\r\n.bx-email-panel p { margin:0 0 16px 0; font:400 16px/1.5 -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif; letter-spacing:-0.048px; color:#43454b; }\r\n.bx-email-panel a { color:#14171e; }\r\n@media (prefers-color-scheme: dark) {\r\n    .bx-email-muted a { color:#a1a1aa !important; }\r\n    .bx-email-bg { background-color:#18181b !important; }\r\n    .bx-email-card { background-color:#18181b !important; }\r\n    .bx-email-panel { background-color:#27272a !important; }\r\n    .bx-email-title { color:#f4f4f5 !important; }\r\n    .bx-email-text, .bx-email-panel p { color:#d4d4d8 !important; }\r\n    .bx-email-panel a { color:#f4f4f5 !important; }\r\n    .bx-email-muted { color:#a1a1aa !important; }\r\n    .bx-email-btn { background-color:#f4f4f5 !important; color:#18181b !important; }\r\n    .bx-email-logo-light { display:none !important; }\r\n    .bx-email-logo-dark { display:block !important; max-height:none !important; overflow:visible !important; }\r\n}\r\n</style>\r\n</head>\r\n<body dir="ltr" lang="en" class="bx-email-bg" bgcolor="#f3f4f6" style="background-color:#f3f4f6; margin:0; padding:0;">\r\n<table border="0" width="100%" cellpadding="0" cellspacing="0" role="presentation" align="center">\r\n<tbody><tr>\r\n<td class="bx-email-bg" bgcolor="#f3f4f6" style="background-color:#f3f4f6; margin:0; text-align:center; font-family:-apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;">\r\n  <!--[if mso]><table role="presentation" width="640" align="center" border="0" cellpadding="0" cellspacing="0"><tr><td><![endif]-->\r\n  <table align="center" width="100%" class="m-mt-0" border="0" cellpadding="0" cellspacing="0" role="presentation" style="max-width:640px; margin:32px auto 0 auto; width:100%;">\r\n  <tbody><tr><td>\r\n    <table align="center" width="100%" class="bx-email-card" border="0" cellpadding="0" cellspacing="0" role="presentation" style="background-color:#ffffff;">\r\n    <tbody><tr>\r\n    <td class="m-px-2" style="padding:16px 24px;">\r\n\r\n      <table align="center" width="100%" border="0" cellpadding="0" cellspacing="0" role="presentation" style="margin-bottom:12px;">\r\n      <tbody><tr>\r\n        <td class="bx-email-title" style="padding:7px 24px 7px 24px; vertical-align:middle; text-align:left; font:600 18px/1.5 -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif; color:#14171e;">{site_logo}</td>\r\n        <td align="right" class="bx-email-muted" style="padding:7px 24px 7px 0; vertical-align:middle; font:13px/1.5 -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif; color:#7b7d81; text-align:right;">{site_name}</td>\r\n      </tr></tbody>\r\n      </table>\r\n\r\n      <table align="center" width="100%" class="bx-email-panel" border="0" cellpadding="0" cellspacing="0" role="presentation" style="background-color:#f3f4f6; border-radius:8px; text-align:center;">\r\n      <tbody><tr>\r\n      <td class="m-px-6 m-py-12" style="padding:64px 40px; text-align:center; font-family:-apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;">\r\n' WHERE `name` = 'site_email_html_template_header' AND REPLACE(`value`, '\r', '') = REPLACE('<html>\r\n    <head>\r\n        <meta name="color-scheme" content="light dark">\r\n        <meta name="supported-color-schemes" content="light dark">\r\n        <style>\r\n            :root { color-scheme: light dark; supported-color-schemes: light dark; }\r\n            @media (prefers-color-scheme: dark) {\r\n                .bx-email-bg { background-color:#18181b !important; }\r\n                .bx-email-text { color:#e4e4e7 !important; }\r\n                .bx-email-muted { color:#a1a1aa !important; }\r\n                .bx-email-line { border-color:#3f3f46 !important; }\r\n                .bx-email-bg a { color:#8ab4f8 !important; }\r\n                .bx-email-logo-light { display:none !important; }\r\n                .bx-email-logo-dark { display:block !important; max-height:none !important; overflow:visible !important; }\r\n            }\r\n        </style>\r\n    </head>\r\n    <body bgcolor="#fff" class="bx-email-bg" style="margin:0; padding:0;">\r\n        <div class="bx-email-bg" style="background-color:#fff;">\r\n            <table width="100%" border="0" cellspacing="0" cellpadding="0" align="center">\r\n                <tr><td valign="top">\r\n                    <div class="bx-email-text" style="color:#333; padding:20px; font:14px Helvetica, Arial, sans-serif;">\r\n                        <div class="bx-email-line bx-email-muted" style="border-bottom:2px solid #eee; padding-bottom:10px; margin-bottom:20px; font-weight:bold; font-size:22px; color:#666;">{site_logo}</div>', '\r', '');
UPDATE `sys_options` SET `value` = '      </td>\r\n      </tr></tbody>\r\n      </table>\r\n\r\n      <table align="center" width="100%" border="0" cellpadding="0" cellspacing="0" role="presentation">\r\n      <tbody><tr>\r\n      <td class="bx-email-muted" style="padding:40px 24px; text-align:center; font:11px/1.5 -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif; color:#7b7d81;">\r\n        {about_us}&nbsp;&nbsp;&nbsp;{unsubscribe}\r\n      </td>\r\n      </tr></tbody>\r\n      </table>\r\n\r\n    </td></tr></tbody>\r\n    </table>\r\n  </td></tr></tbody>\r\n  </table>\r\n  <!--[if mso]></td></tr></table><![endif]-->\r\n</td>\r\n</tr></tbody>\r\n</table>\r\n</body>\r\n</html>' WHERE `name` = 'site_email_html_template_footer' AND REPLACE(`value`, '\r', '') = REPLACE('\r\n                    </div>\r\n                </td></tr>\r\n                <tr><td valign="top">\r\n                    <div class="bx-email-muted" style="color:#666; padding:0 20px 20px 20px; font:11px Helvetica, Arial, sans-serif;">\r\n                        <div class="bx-email-line" style="border-top:2px solid #eee; padding-top:10px;">{about_us}&nbsp;&nbsp;&nbsp;{unsubscribe}</div>\r\n                    </div>\r\n                </td></tr>\r\n            </table>\r\n        </div>\r\n    </body>\r\n</html>', '\r', '');
